const input = { ...$input.first().json };
function buildQs(obj) { return Object.entries(obj).filter(([k,v]) => v !== undefined && v !== null).map(([k,v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&'); }

const action = input.action || '';

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pgHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

const allCreds = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.confluence&select=cred_key,cred_value',
  headers: pgHeaders
});
const creds = {};
for (const c of (allCreds || [])) creds[c.cred_key] = c.cred_value;
if (!creds.atlassian_email || !creds.atlassian_api_token || !creds.atlassian_site) {
  return [{ json: { error: 'Confluence credentials not configured. Need atlassian_email, atlassian_api_token, atlassian_site. If Jira is installed, these are shared automatically.' } }];
}

const site = creds.atlassian_site.replace(/^https?:\/\//, '').replace(/\/$/, '');
const V2 = 'https://' + site + '/wiki/api/v2';
const V1 = 'https://' + site + '/wiki/rest/api';
const basic = Buffer.from(creds.atlassian_email + ':' + creds.atlassian_api_token).toString('base64');
const authHeaders = { 'Authorization': 'Basic ' + basic, 'Accept': 'application/json' };

// Leere Werte zaehlen als "nicht gesetzt". n8n veroeffentlicht JEDES deklarierte
// Feld als Pflichtfeld, deshalb fuellt der Aufrufer fehlende Felder mit "" auf,
// und Modelle schicken ohnehin gern leere Strings mit. Ohne diese Normalisierung
// sind alle undefined-Pruefungen weiter unten wirkungslos - insbesondere die
// Alias-Aufloesung content -> body, was dazu fuehrte, dass update_page den alten
// Inhalt zurueckschrieb und trotzdem Erfolg meldete.
for (const _k of Object.keys(input)) {
  if (input[_k] === '' || input[_k] === null) delete input[_k];
}

// Parameter-Aliasse tolerant behandeln (gaengige LLM-Varianten)
if (input.content !== undefined && input.body === undefined) input.body = input.content;
if (input.max_results !== undefined && input.limit === undefined) input.limit = input.max_results;
if (input.space_key && !input.space_id) {
  try {
    const _sp = await helpers.httpRequest({ method: 'GET', url: V2 + '/spaces?keys=' + encodeURIComponent(String(input.space_key)) + '&limit=1', headers: authHeaders });
    if (_sp.results && _sp.results.length) input.space_id = _sp.results[0].id;
  } catch (_e) {}
}
const jsonHeaders = { ...authHeaders, 'Content-Type': 'application/json' };

function truncate(text, max) {
  max = max || 5000;
  if (text.length > max) return text.substring(0, max) + '\n\n... (truncated, ' + text.length + ' chars total)';
  return text;
}

function stripHtml(html) {
  if (!html) return '';
  return String(html)
    .replace(/<br\s*\/?>(\n)?/gi, '\n')
    .replace(/<\/(p|h[1-6]|li|div)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// --- Inhaltstyp: Pages und Blogposts liegen unter verschiedenen v2-Pfaden ---
const CT_ALIAS = { page: 'page', pages: 'page', blog: 'blogpost', blogpost: 'blogpost', blogposts: 'blogpost', 'blog-post': 'blogpost', blog_post: 'blogpost', news: 'blogpost' };
const ctHint = CT_ALIAS[String(input.content_type || '').trim().toLowerCase()] || null;

function ctPath(kind) { return kind === 'blogpost' ? '/blogposts/' : '/pages/'; }
function ctLabel(kind) { return kind === 'blogpost' ? 'Blogpost' : 'Page'; }

function statusOf(e) {
  return String((e && (e.statusCode || e.httpCode || (e.response && (e.response.status || e.response.statusCode)))) || '');
}

function is404(e) {
  if (statusOf(e) === '404') return true;
  return /\b404\b|not found/i.test(String((e && e.message) || ''));
}

// Confluence antwortet auf eine Unterressource mit falschem Typ (etwa
// /pages/<blogpostId>/footer-comments) mit 400 statt 404. Beide Codes heissen
// hier also "falscher Typ, probiere den anderen". Auth- und Serverfehler
// duerfen NICHT so behandelt werden: die bedeuten nie, dass der andere Typ passt.
function isTypeMismatch(e) {
  const s = statusOf(e);
  if (s === '404' || s === '400') return true;
  if (s) return false;
  return /\b(400|404)\b|not found|bad request/i.test(String((e && e.message) || ''));
}

// Holt dieselbe Ressource unter /pages/ oder /blogposts/ -> { kind, data }
// Der Probe-Request IST der Nutz-Request: im Normalfall (Page) kostet das nichts.
async function contentGet(id, suffix) {
  const order = ctHint === 'blogpost' ? ['blogpost', 'page'] : ['page', 'blogpost'];
  let firstErr = null;
  for (const kind of order) {
    try {
      const data = await helpers.httpRequest({ method: 'GET', url: V2 + ctPath(kind) + encodeURIComponent(id) + (suffix || ''), headers: authHeaders });
      return { kind: kind, data: data };
    } catch (e) {
      if (!firstErr) firstErr = e;
      if (!isTypeMismatch(e)) throw e;
    }
  }
  throw new Error('Content ' + id + ' not found as page or blogpost. Check the id, or it may be in the trash. (' + ((firstErr && firstErr.message) || '') + ')');
}

// Typ ohne Nutzlast ermitteln, fuer POSTs die den Typ vorher brauchen.
async function resolveKind(id) {
  if (ctHint) return ctHint;
  for (const kind of ['page', 'blogpost']) {
    try {
      const r = await helpers.httpRequest({ method: 'GET', url: V2 + (kind === 'blogpost' ? '/blogposts' : '/pages') + '?id=' + encodeURIComponent(id) + '&limit=1', headers: authHeaders });
      if (r && r.results && r.results.length) return kind;
    } catch (e) { /* weiter */ }
  }
  return null;
}

// _links.webui ist die einzige Quelle, die fuer Blogposts die richtige URL-Form
// (/spaces/KEY/blog/JJJJ/MM/TT/id) liefert.
function contentUrl(obj, id, kind) {
  if (obj && obj._links && obj._links.webui) return (obj._links.base || ('https://' + site + '/wiki')) + obj._links.webui;
  if (kind === 'blogpost') return 'https://' + site + '/wiki/pages/viewpage.action?pageId=' + id;
  return 'https://' + site + '/wiki/spaces/_/pages/' + id;
}

// --- Live Docs speichern ihren Inhalt als ADF, nicht als storage-HTML ---
function adfToText(node, depth, ordinal) {
  if (!node) return '';
  if (typeof node === 'string') {
    try { node = JSON.parse(node); } catch (e) { return String(node); }
  }
  depth = depth || 0;
  const kids = Array.isArray(node.content) ? node.content : [];
  const a = node.attrs || {};
  const inner = () => kids.map(k => adfToText(k, depth, 0)).join('');
  const block = () => kids.map((k, i) => adfToText(k, depth, i + 1)).join('');
  switch (node.type) {
    case 'doc': return block();
    case 'paragraph': return inner().replace(/\s+$/, '') + '\n\n';
    case 'heading': return '\n' + '#'.repeat(Math.max(1, Math.min(6, a.level || 1))) + ' ' + inner().trim() + '\n\n';
    case 'text': {
      let t = node.text || '';
      for (const m of (node.marks || [])) {
        if (m.type === 'code') t = '`' + t + '`';
        else if (m.type === 'strong') t = '**' + t + '**';
        else if (m.type === 'em') t = '*' + t + '*';
        else if (m.type === 'link' && m.attrs && m.attrs.href) t = '[' + t + '](' + m.attrs.href + ')';
      }
      return t;
    }
    case 'hardBreak': return '\n';
    case 'bulletList': return kids.map(k => adfToText(k, depth + 1, 0)).join('') + '\n';
    case 'orderedList': return kids.map((k, i) => adfToText(k, depth + 1, i + 1)).join('') + '\n';
    case 'listItem': return '  '.repeat(Math.max(0, depth - 1)) + (ordinal ? (ordinal + '. ') : '- ') + inner().trim().replace(/\n+/g, ' ') + '\n';
    case 'codeBlock': return '```' + (a.language || '') + '\n' + inner() + '\n```\n\n';
    case 'blockquote': return inner().split('\n').map(l => l ? '> ' + l : l).join('\n');
    case 'rule': return '\n---\n\n';
    case 'table': return '\n' + block() + '\n';
    case 'tableRow': return '| ' + kids.map(k => adfToText(k, depth, 0).replace(/\s+/g, ' ').trim()).join(' | ') + ' |\n';
    case 'tableHeader':
    case 'tableCell': return inner();
    case 'inlineCard':
    case 'blockCard': return a.url ? (a.url + ' ') : '';
    case 'mention': return a.text || '@user';
    case 'emoji': return a.text || a.shortName || '';
    case 'status': return '[' + (a.text || '') + ']';
    case 'date': return a.timestamp ? new Date(Number(a.timestamp)).toISOString().substring(0, 10) : '';
    case 'mediaSingle':
    case 'mediaGroup': return '[attachment]\n';
    case 'expand':
    case 'nestedExpand': return '[+] ' + (a.title || '') + '\n' + block();
    default: return kids.length ? block() : '';
  }
}

// Liefert lesbaren Text, egal ob storage-HTML oder ADF -> { text, isLive }
async function readBody(id, kind, data) {
  const st = (data.body && data.body.storage) ? (data.body.storage.value || '') : '';
  if (st) return { text: stripHtml(st), isLive: false };
  try {
    const adfRes = await helpers.httpRequest({ method: 'GET', url: V2 + ctPath(kind) + encodeURIComponent(id) + '?body-format=atlas_doc_format', headers: authHeaders });
    const raw = (adfRes.body && adfRes.body.atlas_doc_format) ? adfRes.body.atlas_doc_format.value : '';
    if (raw) return { text: adfToText(raw).replace(/\n{3,}/g, '\n\n').trim(), isLive: true };
  } catch (e) { /* fallthrough */ }
  return { text: '', isLive: true };
}

// === list_spaces ===
if (action === 'list_spaces') {
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: V2 + '/spaces?limit=100', headers: authHeaders });
    const items = r.results || [];
    if (items.length === 0) return [{ json: { result: 'No spaces found.' } }];
    let out = 'Spaces (' + items.length + '):\n';
    for (const s of items) {
      out += '  [' + s.id + '] ' + (s.key || '?') + ' — ' + (s.name || '') + ' (' + (s.type || 'space') + ')\n';
    }
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence list_spaces failed: ' + err.message } }];
  }

// === list_pages_in_space ===
} else if (action === 'list_pages_in_space') {
  const spaceId = input.space_id;
  if (!spaceId) return [{ json: { error: 'Parameter "space_id" is required (numeric id from list_spaces).' } }];
  const limit = Math.min(parseInt(input.limit) || 25, 100);
  try {
    const lines = [];
    if (ctHint !== 'blogpost') {
      const rp = await helpers.httpRequest({ method: 'GET', url: V2 + '/spaces/' + encodeURIComponent(spaceId) + '/pages?limit=' + limit, headers: authHeaders });
      for (const p of (rp.results || [])) lines.push('  [' + p.id + '] ' + (p.title || '') + ' (page)');
    }
    if (ctHint !== 'page') {
      try {
        const rb = await helpers.httpRequest({ method: 'GET', url: V2 + '/spaces/' + encodeURIComponent(spaceId) + '/blogposts?limit=' + limit, headers: authHeaders });
        for (const p of (rb.results || [])) lines.push('  [' + p.id + '] ' + (p.title || '') + ' (blogpost)');
      } catch (e) { /* Space ohne Blog */ }
    }
    if (lines.length === 0) return [{ json: { result: 'No pages or blogposts in space ' + spaceId + '.' } }];
    let out = 'Content in space ' + spaceId + ' (' + lines.length + '):\n' + lines.join('\n') + '\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence list_pages_in_space failed: ' + err.message } }];
  }

// === search_pages ===
} else if (action === 'search_pages') {
  const query = input.query;
  if (!query) return [{ json: { error: 'Parameter "query" is required. Use CQL (e.g. \'text ~ "onboarding"\', \'space = MARKETING AND type = page\') or plain text (auto-wrapped as text~query).' } }];
  const limit = Math.min(parseInt(input.limit) || 10, 50);
  // Blogposts sind gleichberechtigt: 'type = page' hat sie systematisch
  // ausgefiltert. Nur mit content_type wird wieder eingeschraenkt.
  const typeFilter = ctHint === 'blogpost' ? 'type = blogpost' : (ctHint === 'page' ? 'type = page' : 'type in (page, blogpost)');
  let cql = query;
  // Nur = und ~ verraten echtes CQL. Das frueher mitgepruefte AND/OR liess
  // Klartext wie "onboarding and offboarding" faelschlich als CQL durchgehen.
  if (!/[=~]/.test(cql)) {
    const esc = s => s.replace(/"/g, '\\"');
    const words = cql.trim().split(/\s+/).filter(wd => wd.length > 2);
    if (words.length > 1) {
      // Mehrere Suchwoerter: Phrase ODER Einzelwoerter (statt nie-matchender Ein-Phrasen-Suche)
      cql = typeFilter + ' AND (text ~ "' + esc(cql) + '" OR ' + words.map(wd => 'text ~ "' + esc(wd) + '"').join(' OR ') + ')';
    } else {
      cql = typeFilter + ' AND text ~ "' + esc(cql) + '"';
    }
  }
  try {
    const qs = buildQs({ cql, limit: String(limit) });
    const r = await helpers.httpRequest({ method: 'GET', url: V1 + '/content/search?' + qs, headers: authHeaders });
    const items = r.results || [];
    if (items.length === 0) return [{ json: { result: 'No pages matched CQL: ' + cql + '. Note: Confluence search index may lag on newly created pages — try list_pages_in_space as fallback.' } }];
    let out = 'Pages matched (' + items.length + '):\n';
    for (const p of items) out += '  [' + p.id + '] ' + (p.title || '') + ' (' + (p.type || 'page') + ')\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence search_pages failed: ' + err.message } }];
  }

// === get_page ===
} else if (action === 'get_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  try {
    const got = await contentGet(pageId, '?body-format=storage');
    const r = got.data;
    let out = '**' + (r.title || '') + '** [' + ctLabel(got.kind) + ' id: ' + r.id + ']\n';
    if (r.spaceId) out += 'Space id: ' + r.spaceId + '\n';
    if (r.parentId) out += 'Parent id: ' + r.parentId + '\n';
    if (r.version) out += 'Version: ' + r.version.number + '  (pass this as expected_version to update_page for a safe edit)\n';
    if (r.authorId) out += 'Author id: ' + r.authorId + '\n';
    if (r.createdAt) out += 'Created: ' + r.createdAt.substring(0, 10) + '\n';
    // format=storage liefert das rohe Markup. Noetig, wenn der Agent eine Seite
    // wirklich aendern soll: aus aufbereitetem Text laesst sich die Formatierung
    // (Spaltenbreiten, Makros) nicht rekonstruieren.
    const wantRaw = /^(storage|html|raw)$/i.test(String(input.format || '').trim());
    if (wantRaw) {
      const raw = (r.body && r.body.storage) ? (r.body.storage.value || '') : '';
      if (!raw) {
        out += '\nBody: (no storage representation, this content is ADF only)\n';
        return [{ json: { result: truncate(out) } }];
      }
      const LIMIT = 20000;
      if (raw.length > LIMIT) {
        out += '\nWARNING: the raw body is ' + raw.length + ' chars and is shown truncated below. Do NOT write this truncated text back with update_page, it would delete the rest of the page. Use append_to_page to add something.\n';
        out += '\nBody (storage, TRUNCATED):\n' + raw.substring(0, LIMIT) + '\n';
      } else {
        out += '\nBody (storage format, use exactly this markup when updating):\n' + raw + '\n';
      }
      out += '\n' + contentUrl(r, r.id, got.kind);
      return [{ json: { result: out } }];
    }
    const bi = await readBody(r.id, got.kind, r);
    if (bi.isLive) out += 'Format: ADF only - readable here, but update_page cannot write it.\n';
    out += bi.text ? ('\nBody:\n' + bi.text + '\n') : '\nBody: (empty)\n';
    out += '\n' + contentUrl(r, r.id, got.kind);
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence get_page failed: ' + err.message } }];
  }

// === get_page_by_title ===
} else if (action === 'get_page_by_title') {
  const title = input.title;
  if (!title) return [{ json: { error: 'Parameter "title" is required (exact title, ASCII works best).' } }];
  const spaceId = input.space_id;
  try {
    let items = [];
    let kind = 'page';
    if (ctHint !== 'blogpost') {
      let url = V2 + '/pages?title=' + encodeURIComponent(title);
      if (spaceId) url += '&space-id=' + encodeURIComponent(spaceId);
      const r = await helpers.httpRequest({ method: 'GET', url, headers: authHeaders });
      items = r.results || [];
    }
    if (items.length === 0 && ctHint !== 'page') {
      try {
        let burl = V2 + '/blogposts?title=' + encodeURIComponent(title);
        if (spaceId) burl += '&space-id=' + encodeURIComponent(spaceId);
        const rb = await helpers.httpRequest({ method: 'GET', url: burl, headers: authHeaders });
        if (rb.results && rb.results.length) { items = rb.results; kind = 'blogpost'; }
      } catch (e) { /* keine Blogposts */ }
    }
    if (items.length === 0) return [{ json: { result: 'No page or blogpost with title "' + title + '"' + (spaceId ? ' in space ' + spaceId : '') + '. Titles with em-dashes or diacritics may not match — try search_pages instead.' } }];
    let out = ctLabel(kind) + 's matching title "' + title + '" (' + items.length + '):\n';
    for (const p of items) out += '  [' + p.id + '] ' + (p.title || '') + ' (space: ' + (p.spaceId || '?') + ', v' + (p.version ? p.version.number : '?') + ')\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence get_page_by_title failed: ' + err.message } }];
  }

// === list_children ===
} else if (action === 'list_children') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  const limit = Math.min(parseInt(input.limit) || 25, 100);
  try {
    const r = await helpers.httpRequest({ method: 'GET', url: V2 + '/pages/' + encodeURIComponent(pageId) + '/children?limit=' + limit, headers: authHeaders });
    const items = r.results || [];
    if (items.length === 0) return [{ json: { result: 'Page ' + pageId + ' has no child pages.' } }];
    let out = 'Children of ' + pageId + ' (' + items.length + '):\n';
    for (const p of items) out += '  [' + p.id + '] ' + (p.title || '') + '\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    // Blogposts koennen keine Kinder haben - das ist kein Fehler, sondern eine Aussage.
    if (is404(err)) return [{ json: { result: 'No child pages for ' + pageId + '. Note: blogposts cannot have child pages, and the id may not exist.' } }];
    return [{ json: { error: 'Confluence list_children failed: ' + err.message } }];
  }

// === create_page ===
} else if (action === 'create_page') {
  const spaceId = input.space_id;
  const title = input.title;
  const body = input.body;
  if (!spaceId) return [{ json: { error: 'Parameter "space_id" is required (numeric id from list_spaces).' } }];
  if (!title) return [{ json: { error: 'Parameter "title" is required.' } }];
  if (!body) return [{ json: { error: 'Parameter "body" is required (HTML in storage format, e.g. "<p>Hello</p>").' } }];
  const kind = ctHint === 'blogpost' ? 'blogpost' : 'page';
  const payload = {
    spaceId: String(spaceId),
    status: 'current',
    title: String(title),
    body: { representation: 'storage', value: String(body) }
  };
  // Blogposts haben keinen Parent, parent_id wird dort bewusst ignoriert.
  if (kind === 'page' && input.parent_id) payload.parentId = String(input.parent_id);
  try {
    const r = await helpers.httpRequest({ method: 'POST', url: V2 + (kind === 'blogpost' ? '/blogposts' : '/pages'), headers: jsonHeaders, body: JSON.stringify(payload) });
    return [{ json: { result: ctLabel(kind) + ' created [id: ' + r.id + ']: ' + r.title + ' (title: "' + String(title) + '", body: ' + String(body).length + ' chars)\n' + contentUrl(r, r.id, kind) } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Confluence create_page failed: ' + msg } }];
  }

// === update_page ===
} else if (action === 'update_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  if (!input.title && !input.body) return [{ json: { error: 'Provide at least one of: title, body.' } }];
  try {
    const got = await contentGet(pageId, '?body-format=storage');
    const current = got.data;
    const kind = got.kind;
    const curVer = (current.version && current.version.number) ? current.version.number : 1;

    // 1. Optimistic locking: der Agent liest die Seite, baut Minuten spaeter den
    //    neuen Text - editiert in der Zwischenzeit ein Mensch, wuerde die fremde
    //    Aenderung stillschweigend ueberschrieben (Confluence merkt nichts, weil
    //    die frisch gelesene Versionsnummer stimmig ist).
    const expRaw = (input.expected_version === undefined || input.expected_version === null) ? '' : String(input.expected_version).trim();
    if (expRaw !== '') {
      const exp = parseInt(expRaw, 10);
      if (!isNaN(exp) && exp !== curVer) {
        return [{ json: { error: 'Version conflict on ' + ctLabel(kind).toLowerCase() + ' ' + pageId + ': you expected v' + exp + ', current is v' + curVer + '. Someone edited it in the meantime. NOTHING was written. Re-read it with get_page, merge your change into the current text, then retry with expected_version=' + curVer + '.' } }];
      }
    }

    const curStorage = (current.body && current.body.storage) ? (current.body.storage.value || '') : '';

    // 2. Der zerstoererische Fall ist NICHT "Live Doc", sondern "kein
    //    storage-Body vorhanden". Viele Live Docs liefern sehr wohl eine
    //    storage-Repraesentation und werden seit jeher ueber sie geschrieben;
    //    nur wenn ausschliesslich ADF existiert, wuerde ein storage-Write den
    //    Inhalt vernichten.
    if (!curStorage && current.body && current.body.atlas_doc_format) {
      return [{ json: { error: 'This content exists only in ADF format and has no storage representation, so writing storage-format HTML would erase everything. This skill refuses to do that. NOTHING was written. You can read it with get_page or comment with add_comment_to_page; editing has to happen in the Confluence UI.' } }];
    }

    // 3. Wipe-Guard: nur title gesetzt, aber der alte Body kam leer zurueck.
    if (!input.body && !curStorage) {
      return [{ json: { error: 'Refusing to update: only "title" was given, but the current body came back empty in storage format. Writing now would erase the content. NOTHING was written. Read the content with get_page first and send the full body together with the new title.' } }];
    }

    // 4. Schrumpf-Schutz. Eine deutlich kuerzere Fassung ist fast immer eine
    //    misslungene Rekonstruktion: das Modell baut die Seite aus dem
    //    aufbereiteten Text nach und verliert dabei Spaltenbreiten, Makros und
    //    im schlimmsten Fall fremde Eintraege. Gemessener Fall: 9.869 -> 4.265
    //    Zeichen bei unveraendertem Inhalt.
    if (input.body && curStorage) {
      const beforeLen = curStorage.length;
      const afterLen = String(input.body).length;
      const allowShrink = /^(1|true|yes|ja)$/i.test(String(input.allow_shrink || '').trim());
      if (!allowShrink && beforeLen >= 500 && afterLen < beforeLen * 0.7) {
        return [{ json: { error: 'Refusing to update: the new body is only ' + Math.round(afterLen / beforeLen * 100) + ' percent of the current one (' + afterLen + ' vs ' + beforeLen + ' chars). That usually means formatting such as column widths and macros, or entries written by other people, were lost while rebuilding the page. NOTHING was written. To ADD a row or a paragraph use append_to_page. To edit precisely, call get_page with format=storage and change that exact markup. If the shrink really is intended, repeat this call with allow_shrink=true.' } }];
      }
    }

    const nextVersion = curVer + 1;
    const note = input.change_note ? (' - ' + String(input.change_note)) : '';
    const payload = {
      id: String(pageId),
      status: 'current',
      title: input.title || current.title,
      body: { representation: 'storage', value: input.body || curStorage },
      version: { number: nextVersion, message: 'Rupert (KI-Agent)' + note }
    };
    const r = await helpers.httpRequest({ method: 'PUT', url: V2 + ctPath(kind) + encodeURIComponent(pageId), headers: jsonHeaders, body: JSON.stringify(payload) });
    const changed = [];
    if (input.title) changed.push('title: "' + String(input.title) + '"');
    if (input.body) changed.push('body: ' + String(input.body).length + ' chars');
    return [{ json: { result: ctLabel(kind) + ' ' + pageId + ' updated to v' + nextVersion + ': ' + r.title + ' (changed ' + (changed.join(', ') || 'nothing') + ')\n' + contentUrl(r, pageId, kind) } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Confluence update_page failed: ' + msg } }];
  }

// === append_to_page ===
} else if (action === 'append_to_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];

  // Entweder fertiges HTML oder Zellen fuer eine neue Tabellenzeile. Bei cells
  // uebernimmt der Skill das Escaping, damit Umlaute und Sonderzeichen im
  // Feedback-Text die Seite nicht zerlegen.
  let snippet = input.html || input.body || input.content || '';
  let where = String(input.location || '').toLowerCase();
  if (!snippet && input.cells) {
    let cells = input.cells;
    if (typeof cells === 'string') {
      try { cells = JSON.parse(cells); } catch (e) { cells = String(input.cells).split('|'); }
    }
    if (!Array.isArray(cells) || cells.length === 0) {
      return [{ json: { error: 'Parameter "cells" must be a JSON array of strings, e.g. ["31.07.2026","Freddy","Feedback text","Technik","Niedrig","Offen"].' } }];
    }
    const escCell = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    snippet = '<tr>' + cells.map(cd => '<td>' + escCell(cd) + '</td>').join('') + '</tr>';
    if (!where) where = 'table';
  }
  if (!snippet) {
    return [{ json: { error: 'Provide either "html" (a storage-format snippet) or "cells" (JSON array for a new table row).' } }];
  }
  if (!where) where = 'end';

  try {
    const got = await contentGet(pageId, '?body-format=storage');
    const current = got.data;
    const kind = got.kind;
    const curVer = (current.version && current.version.number) ? current.version.number : 1;

    const expRaw = (input.expected_version === undefined || input.expected_version === null) ? '' : String(input.expected_version).trim();
    if (expRaw !== '') {
      const exp = parseInt(expRaw, 10);
      if (!isNaN(exp) && exp !== curVer) {
        return [{ json: { error: 'Version conflict on ' + ctLabel(kind).toLowerCase() + ' ' + pageId + ': you expected v' + exp + ', current is v' + curVer + '. Someone edited it in the meantime. NOTHING was written. Just retry the append, it works on the current content.' } }];
      }
    }

    const curStorage = (current.body && current.body.storage) ? (current.body.storage.value || '') : '';
    if (!curStorage) {
      return [{ json: { error: 'This content has no storage representation (ADF only), so nothing can be appended without rewriting it. NOTHING was written. Add a comment with add_comment_to_page instead, or edit it in the Confluence UI.' } }];
    }

    let newBody;
    if (where === 'table' || where === 'row') {
      const lower = curStorage.toLowerCase();
      let at = lower.lastIndexOf('</tbody>');
      if (at < 0) at = lower.lastIndexOf('</table>');
      if (at < 0) {
        return [{ json: { error: 'No table found on this page, so a row cannot be appended. Use location=end to append at the bottom of the page. NOTHING was written.' } }];
      }
      newBody = curStorage.slice(0, at) + snippet + curStorage.slice(at);
    } else {
      newBody = curStorage + snippet;
    }

    const note = input.change_note ? (' - ' + String(input.change_note)) : '';
    const payload = {
      id: String(pageId),
      status: 'current',
      title: current.title,
      body: { representation: 'storage', value: newBody },
      version: { number: curVer + 1, message: 'Rupert (KI-Agent)' + note }
    };
    const r = await helpers.httpRequest({ method: 'PUT', url: V2 + ctPath(kind) + encodeURIComponent(pageId), headers: jsonHeaders, body: JSON.stringify(payload) });
    const place = (where === 'table' || where === 'row') ? 'into the last table' : 'at the end of the page';
    return [{ json: { result: ctLabel(kind) + ' ' + pageId + ': appended ' + snippet.length + ' chars ' + place + ', now v' + (curVer + 1) + ' (page grew from ' + curStorage.length + ' to ' + newBody.length + ' chars): ' + r.title + '\n' + contentUrl(r, pageId, kind) } }];
  } catch (err) {
    const msg = (err.response && err.response.body) ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Confluence append_to_page failed: ' + msg } }];
  }

// === delete_page ===
} else if (action === 'delete_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  try {
    const kind = await resolveKind(pageId);
    if (!kind) return [{ json: { error: 'No page or blogpost with id ' + pageId + ' found.' } }];
    await helpers.httpRequest({ method: 'DELETE', url: V2 + ctPath(kind) + encodeURIComponent(pageId), headers: authHeaders });
    return [{ json: { result: ctLabel(kind) + ' ' + pageId + ' deleted (moved to trash).' } }];
  } catch (err) {
    return [{ json: { error: 'Confluence delete_page failed: ' + err.message } }];
  }

// === add_comment_to_page ===
} else if (action === 'add_comment_to_page') {
  const pageId = input.page_id;
  const text = input.text;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  if (!text) return [{ json: { error: 'Parameter "text" is required.' } }];
  const value = /<[a-z][^>]*>/i.test(text) ? text : '<p>' + String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</p>';
  try {
    const kind = await resolveKind(pageId);
    if (!kind) return [{ json: { error: 'No page or blogpost with id ' + pageId + ' found.' } }];
    // v2 erwartet fuer Blogposts den Key blogPostId, nicht pageId.
    const payload = { body: { representation: 'storage', value } };
    if (kind === 'blogpost') payload.blogPostId = String(pageId); else payload.pageId = String(pageId);
    const r = await helpers.httpRequest({ method: 'POST', url: V2 + '/footer-comments', headers: jsonHeaders, body: JSON.stringify(payload) });
    return [{ json: { result: 'Comment added to ' + ctLabel(kind).toLowerCase() + ' ' + pageId + ' (comment id: ' + r.id + ', ' + String(text).length + ' chars).' } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Confluence add_comment_to_page failed: ' + msg } }];
  }

// === list_comments_on_page ===
} else if (action === 'list_comments_on_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  try {
    const got = await contentGet(pageId, '/footer-comments?body-format=storage&limit=50');
    const items = got.data.results || [];
    if (items.length === 0) return [{ json: { result: 'No comments on ' + ctLabel(got.kind).toLowerCase() + ' ' + pageId + '.' } }];
    let out = 'Comments on ' + ctLabel(got.kind).toLowerCase() + ' ' + pageId + ' (' + items.length + '):\n\n';
    for (const c of items) {
      const body = c.body && c.body.storage ? stripHtml(c.body.storage.value) : '';
      out += '  [' + c.id + '] ' + body + '\n';
    }
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence list_comments_on_page failed: ' + err.message } }];
  }

// === add_label_to_page ===
} else if (action === 'add_label_to_page') {
  const pageId = input.page_id;
  const label = input.label;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  if (!label) return [{ json: { error: 'Parameter "label" is required (e.g. "meeting-notes", "onboarding").' } }];
  const body = [{ prefix: 'global', name: String(label) }];
  try {
    await helpers.httpRequest({ method: 'POST', url: V1 + '/content/' + encodeURIComponent(pageId) + '/label', headers: jsonHeaders, body: JSON.stringify(body) });
    return [{ json: { result: 'Label "' + label + '" added to page ' + pageId + '.' } }];
  } catch (err) {
    const msg = err.response && err.response.body ? JSON.stringify(err.response.body) : err.message;
    return [{ json: { error: 'Confluence add_label_to_page failed: ' + msg } }];
  }

// === list_labels_on_page ===
} else if (action === 'list_labels_on_page') {
  const pageId = input.page_id;
  if (!pageId) return [{ json: { error: 'Parameter "page_id" is required.' } }];
  try {
    const got = await contentGet(pageId, '/labels');
    const items = got.data.results || [];
    if (items.length === 0) return [{ json: { result: 'No labels on ' + ctLabel(got.kind).toLowerCase() + ' ' + pageId + '.' } }];
    let out = 'Labels on ' + ctLabel(got.kind).toLowerCase() + ' ' + pageId + ' (' + items.length + '):\n';
    for (const l of items) out += '  ' + (l.name || '') + ' (prefix: ' + (l.prefix || 'global') + ')\n';
    return [{ json: { result: out } }];
  } catch (err) {
    return [{ json: { error: 'Confluence list_labels_on_page failed: ' + err.message } }];
  }

// === search_by_label ===
} else if (action === 'search_by_label') {
  const label = input.label;
  if (!label) return [{ json: { error: 'Parameter "label" is required.' } }];
  const limit = Math.min(parseInt(input.limit) || 25, 100);
  let cql = 'label = "' + String(label).replace(/"/g, '\\"') + '"';
  if (ctHint === 'blogpost') cql += ' AND type = blogpost';
  else if (ctHint === 'page') cql += ' AND type = page';
  try {
    const qs = buildQs({ cql, limit: String(limit) });
    const r = await helpers.httpRequest({ method: 'GET', url: V1 + '/content/search?' + qs, headers: authHeaders });
    const items = r.results || [];
    if (items.length === 0) return [{ json: { result: 'No content matched label "' + label + '". Note: search index may lag on newly labeled pages.' } }];
    let out = 'Content with label "' + label + '" (' + items.length + '):\n';
    for (const p of items) out += '  [' + p.id + '] ' + (p.title || '') + ' (' + (p.type || 'page') + ')\n';
    return [{ json: { result: truncate(out) } }];
  } catch (err) {
    return [{ json: { error: 'Confluence search_by_label failed: ' + err.message } }];
  }

} else {
  return [{ json: { error: 'Unknown action: "' + action + '". Available: list_spaces, list_pages_in_space, search_pages, get_page, get_page_by_title, list_children, create_page, update_page, append_to_page, delete_page, add_comment_to_page, list_comments_on_page, add_label_to_page, list_labels_on_page, search_by_label.' } }];
}
